package saver

import (
	"context"
	"testing"
)

type gsrWitnessStore struct{ puts int }

func (s *gsrWitnessStore) Put(ctx context.Context, key, value string) error {
	s.puts++
	return ctx.Err()
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	s := &gsrWitnessStore{}
	_ = Save(ctx, s, "id", "a", "b")
	if s.puts != 1 {
		t.Fatalf("Save with a cancelled context made %d Put calls, want 1", s.puts)
	}
}
